settings.custom_css:
#container-plans .eb-pricing-table-wrapper {
        height: 100%;

    display: flex;
    flex-direction: column;
    justify-content: space-between;

}

#container-plans .eb-pricing-table-wrapper .edu-btn {
            margin-top: auto;
}
#container-plans .amount {
    color:#170A07;
    font-family: "DM Mono", Sans-serif;
    font-weight: 500;
    font-size: 50px;
}

#container-plans .eb-price-feature {
   color:#616163;  
}

#container-plans .pricing-features {

    display: flex;
    flex-direction: column;
    align-items: flex-start;
    text-align: left;
}

#first-plan {
    --edublink-color-primary: #3360C4;
    --edublink-color-primary-alt:#39c0fa;
    --edublink-gradient-primary: linear-gradient(-90deg, var(--edublink-color-primary-alt) 0%, var(--edublink-color-primary) 100%);
}




#second-plan {
    --edublink-color-primary: #11544F;
      --edublink-color-primary-alt:#0a875a;
    --edublink-gradient-primary: linear-gradient(-90deg, var(--edublink-color-primary-alt) 0%, var(--edublink-color-primary) 100%);
}

#third-plan {
    --edublink-color-primary: #EA4828;
}
